--   NPC 39190: Wicked Spirit (areaId=4859, 1 spawns)
--   NPC 36597: The Lich King (areaId=4859, 1 spawns)
UPDATE creature SET zoneId = 4859 WHERE zoneId = 4812 AND areaId IN (4859);

