--   NPC 153931: Brewfest Reveler (areaId=809, 6 spawns)
UPDATE creature SET zoneId = 1 WHERE zoneId = 1537 AND areaId IN (809);

-- Pattern: zoneId=1220 (Darnassian Base Camp) -> should be 7502 (Dalaran) -- 1 NPCs, 2 spawns
